function support(){return page('Atendimento','Respostas cuidadosas, com informações de verdade.')+`<div class="info">Simulador local por regras, sem conexão com mensagens das redes sociais. Revise a resposta antes de enviá-la. Nenhuma mensagem é enviada automaticamente.</div><div class="grid-two"><section class="card"><h2>Prepare uma resposta</h2><p class="help">Cole uma dúvida do cliente para consultar as orientações cadastradas.</p><form id="reply-form"><label>Mensagem do cliente<textarea name="message" required maxlength="3000" placeholder="Ex.: Quanto custam 500 envelopes personalizados?"></textarea></label><button class="button">Preparar resposta</button></form><div id="reply" class="reply" aria-live="polite"></div></section><section class="card"><h2>Como atendemos</h2><p class="help">Linguagem natural, cordial, profissional e humanizada.</p><div class="mini-row"><span>Preços</span><span class="badge green">Somente tabela cadastrada</span></div><div class="mini-row"><span>Prazos e disponibilidade</span><span class="badge warn">Confirmação humana</span></div><div class="mini-row"><span>Frete e condições especiais</span><span class="badge warn">Confirmação humana</span></div><p class="help">Solicitar produto, quantidade, nome da igreja, logotipo e dados de personalização. Não solicitar dados sensíveis desnecessários.</p></section></div>`}
