document.addEventListener('click',async e=>{const filter=e.target.closest('[data-schedule-filter]'),tab=e.target.closest('[data-content-tab]'),period=e.target.closest('[data-insights-period]'),create=e.target.closest('[data-content-create]'),addButton=e.target.closest('[data-add]'),deleteButton=e.target.closest('[data-delete]'),stock=e.target.closest('[data-stock]'),copy=e.target.closest('[data-copy]');if(tab){contentTab=tab.dataset.contentTab;render();document.querySelector(`[data-content-tab="${contentTab}"]`)?.focus();return}if(period){insightsPeriod=period.dataset.insightsPeriod;render();document.querySelector(`[data-insights-period="${insightsPeriod}"]`)?.focus();return}if(filter){scheduleFilter=filter.dataset.scheduleFilter;render();document.querySelector(`[data-schedule-filter="${scheduleFilter}"]`)?.focus();return}if(create){document.querySelector('#manual-create')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#post-form select')?.focus();return}if(addButton)modal(addButton.dataset.add);if(stock)modal('stock',Number(stock.dataset.stock));try{if(deleteButton){const table=deleteButton.dataset.delete,id=Number(deleteButton.dataset.id),order=table==='orders'?state.orders.find(item=>item.id===id):null,message=table==='posts'?'Excluir este registro local? Uma publicação já enviada à rede social não será excluída.':table==='orders'&&order?.transaction_id?'Excluir este pedido e a receita vinculada no Financeiro? Esta ação não pode ser desfeita.':table==='orders'?'Excluir este pedido? Esta ação não pode ser desfeita.':'Excluir este registro? Esta ação não pode ser desfeita.';if(confirm(message)){await api('delete',{table,id});await refresh();notify(table==='orders'?'Pedido excluído.':'Registro excluído.')}}if(copy){await navigator.clipboard.writeText(state.posts.find(p=>p.id===Number(copy.dataset.copy)).caption);notify('Legenda copiada. Revise antes de publicar.')}}catch(error){notify(error.message)}});
