document.querySelector('#form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f)),type=f.dataset.type;for(const key of ['amount','total','quantity','minimum'])if(key in data)data[key]=['amount','total'].includes(key)?Math.round(Number(data[key])*100):Number(data[key]);if(['stock','order-income','orders-edit','transactions-edit'].includes(type))data.id=Number(f.dataset.id);const endpoint=type==='stock'?'inventory/quantity':type==='order-income'?'orders/income':type==='orders-edit'?'orders/update':type==='transactions-edit'?'transactions/update':type,save=document.querySelector('#save');save.disabled=true;try{await api(endpoint,data);await refresh();document.querySelector('#modal').close();notify(type==='order-income'?'Receita do pedido registrada no financeiro.':type==='orders-edit'?'Pedido e financeiro atualizados.':type==='transactions-edit'?'Despesa atualizada.':type==='orders'&&data.total>0?'Pedido cadastrado e receita lançada no financeiro.':'Registro salvo com sucesso.')}catch(error){document.querySelector('#form-error').textContent=error.message}finally{save.disabled=false}});
