const toggle=document.querySelector('#menu-toggle'),backdrop=document.querySelector('#menu-backdrop'),sidebar=document.querySelector('#sidebar'),main=document.querySelector('main'),mobileMenu=matchMedia('(max-width:760px)');
sidebar.inert=mobileMenu.matches;
function setMenu(open){document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');backdrop.hidden=!open;sidebar.inert=mobileMenu.matches&&!open;main.inert=open;if(open)document.querySelector('nav a.active')?.focus();else toggle.focus()}
toggle.addEventListener('click',()=>setMenu(!document.body.classList.contains('menu-open')));
backdrop.addEventListener('click',()=>setMenu(false));
document.querySelector('nav').addEventListener('click',e=>{if(e.target.closest('a')&&document.body.classList.contains('menu-open'))setMenu(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open'))setMenu(false)});

mobileMenu.addEventListener('change',()=>{document.body.classList.remove('menu-open');backdrop.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu');sidebar.inert=mobileMenu.matches;main.inert=false});

function renderDraft(p){
 const status=p.publish_status||'draft';
 const group=contentGroup(p),when=p.schedule&&['queued','running','processing'].includes(p.schedule.state)?scheduleParts(p):null;
 const labels={draft:'Rascunho · revisar',scheduled:'Agendado',sending:'Envio em andamento',processing:'Imagem em preparação',review:'Resultado exige conferência',published:'Publicado pela Meta'};
 return `<article class="content-card" id="post-${p.id}" tabindex="-1"><div class="content-card-media">${p.image_name?`<img src="/media/${esc(p.image_name)}" alt="Miniatura de ${esc(p.product)}" loading="lazy">`:visualPlaceholder(p)}<span class="content-state ${group}">${esc(labels[status]||status)}</span>${when?`<span class="content-time">${esc(when.day)} · ${esc(when.time)}</span>`:''}</div><div class="content-card-body"><div class="content-card-meta"><span>${esc(p.channel)}</span><i></i><span>${esc(p.source)}</span></div><h3>${esc(p.product)}</h3>${when?`<p class="content-schedule">${icon('catalog')}<span><b>${esc(when.full)}</b><small>Horário de São Paulo · executor ${state.scheduler?.active?'ativo':'inativo'}</small></span></p>`:''}<details class="content-caption"><summary>Ver legenda</summary><pre>${esc(p.caption)}</pre></details>${p.publish_error?`<p class="publication-error">${esc(p.publish_error)}</p>`:''}<div class="publication-diagnostic" id="diagnostic-${p.id}" aria-live="polite"></div>${p.remote_id?`<p class="help">Identificador na Meta: ${esc(p.remote_id)}</p>`:''}<div class="draft-actions">${status==='draft'?`<button class="button" data-review="${p.id}">Revisar e publicar</button>`:''}${status==='scheduled'?`<button class="button secondary" data-cancel-schedule="${p.id}">Cancelar agendamento</button>`:''}${status==='processing'&&p.schedule?.state!=='processing'&&p.schedule?.state!=='running'?`<button class="button" data-finish="${p.id}">Concluir publicação</button>`:''}${status==='review'?`${p.channel==='Instagram'?`<button class="button secondary" data-test-image="${p.id}">Testar preparação</button><button class="button secondary" data-test-meta-image="${p.id}">Preparar via Meta</button>`:''}<button class="button secondary" data-diagnose="${p.id}">Diagnosticar</button><button class="button secondary" data-reset="${p.id}">Não foi publicada</button>`:''}<button class="button secondary" data-copy="${p.id}">Copiar legenda</button>${['draft','published'].includes(status)?del('posts',p.id):''}</div></div></article>`
}
const publicationDialog=document.querySelector('#publish-modal'),publicationForm=document.querySelector('#publish-form');
document.querySelector('#close-publish').onclick=()=>{if(publicationForm.dataset.uploading!=='true'&&publicationForm.dataset.sending!=='true')publicationDialog.close()};
publicationDialog.addEventListener('cancel',e=>{if(publicationForm.dataset.uploading==='true'||publicationForm.dataset.sending==='true')e.preventDefault()});
function reviewPost(id){
 const post=state.posts.find(p=>p.id===id);
 const accounts=(state.meta.accounts||[]).filter(a=>a.channel===post.channel&&a.publishing_scope_granted);
 publicationForm.dataset.id=id;publicationForm.dataset.revision=post.revision;publicationForm.dataset.image=post.image_name||'';
 document.querySelector('#publish-error').textContent='';
 document.querySelector('#publish-fields').innerHTML=`<p class="help">Canal: <b>${esc(post.channel)}</b>. Confira legenda, imagem e conta antes de confirmar o envio à rede.</p><label>Conta de destino<select name="account_id" required><option value="">Selecione a conta</option>${accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===post.account_id?'selected':''}>${esc(a.channel==='Instagram'?'@'+a.name:a.name)}</option>`).join('')}</select></label>${accounts.length?'':'<p class="publication-error">Verifique as contas e permissões da Meta antes de publicar neste canal.</p>'}<label for="post-caption">Legenda</label><textarea id="post-caption" name="caption" required maxlength="2200" rows="7">${esc(post.caption)}</textarea><label>Data e hora para agendar (São Paulo)<input type="datetime-local" name="when"></label><p class="help">${state.scheduler?.active?'Executor ativo. Confira o horário antes de autorizar o envio automático.':'Executor inativo. O agendamento só será liberado quando o processo automático estiver configurado e ativo.'} O executor confere a fila a cada 30–60 segundos. Atrasos acima de 30 minutos exigem revisão.</p><label>Imagem JPEG (até 5 MB)<input type="file" id="post-file" accept="image/jpeg"></label><p class="help">Use uma arte final, por exemplo 1080 × 1080 px. Ao enviar, a imagem ficará acessível por um link público para a Meta buscar. Não envie dados privados.</p><img id="image-preview" class="post-image" ${post.image_name?`src="/media/${esc(post.image_name)}"`:'hidden'} alt="Prévia da imagem"><button class="button secondary" type="button" id="remove-post-image">Remover imagem do rascunho</button>`;
 document.querySelector('#post-file').addEventListener('change',async e=>{
  const file=e.target.files[0];if(!file)return;
  const error=document.querySelector('#publish-error');error.textContent='';
  if(file.type!=='image/jpeg'||file.size>5*1024*1024){error.textContent='Selecione um JPEG de até 5 MB.';e.target.value='';return}
  e.target.disabled=true;publicationForm.dataset.uploading='true';publicationForm.querySelectorAll('[type=submit]').forEach(b=>b.disabled=true);
  try{const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file)});const image=await api('media',{data:encoded});publicationForm.dataset.image=image.name;const preview=document.querySelector('#image-preview');preview.src=image.url;preview.hidden=false}catch(e){error.textContent=e.message}finally{e.target.disabled=false;publicationForm.dataset.uploading='false';publicationForm.querySelectorAll('[type=submit]').forEach(b=>b.disabled=false)}
 });
 document.querySelector('#remove-post-image').onclick=()=>{publicationForm.dataset.image='';document.querySelector('#image-preview').hidden=true;document.querySelector('#post-file').value=''};
 publicationDialog.showModal();
}
publicationForm.addEventListener('submit',async e=>{
 e.preventDefault();if(publicationForm.dataset.uploading==='true')return;
 const data=Object.fromEntries(new FormData(publicationForm));data.id=Number(publicationForm.dataset.id);data.revision=Number(publicationForm.dataset.revision);data.image_name=publicationForm.dataset.image;
 const send=e.submitter?.value==='publish',schedule=e.submitter?.value==='schedule';const post=state.posts.find(p=>p.id===data.id);const account=(state.meta.accounts||[]).find(a=>a.id===data.account_id&&a.channel===post.channel);
 if(schedule&&(!state.scheduler?.active||!data.when)){document.querySelector('#publish-error').textContent='Ative o executor e escolha a data e hora antes de agendar.';return}
 if(schedule&&!confirm(`Autorizar o envio automático no ${post.channel}, conta ${account?.name||''}, em ${data.when.replace('T',' às ')} (São Paulo), mesmo com o site fechado?`))return;
 if(send&&!confirm(`Publicar agora no ${post.channel}, na conta ${account?.name||''}? Confira a legenda e a imagem antes de confirmar.`))return;
 publicationForm.dataset.sending='true';publicationForm.querySelectorAll('[type=submit]').forEach(b=>b.disabled=true);document.querySelector('#publish-error').textContent='';
 try{const saved=await api('posts/update',data);publicationForm.dataset.revision=saved.revision;if(schedule){await api('posts/schedule',{id:data.id,revision:saved.revision,when:data.when,confirmed:true});notify('Agendamento salvo. Você pode cancelar enquanto o envio não tiver começado.')}else if(send){const result=await api('posts/publish',{id:data.id,revision:saved.revision,confirmed:true});notify(result.status==='processing'?'Imagem enviada para preparação. Use Concluir publicação no Instagram quando estiver pronta.':'A Meta confirmou a publicação.')}else notify('Rascunho salvo. Nada foi publicado.');publicationDialog.close();await refresh()}catch(error){document.querySelector('#publish-error').textContent=error.message;await refresh().catch(()=>{});if(state.posts.find(p=>p.id===data.id)?.publish_status!=='draft'){publicationDialog.close();notify(error.message)}}finally{publicationForm.dataset.sending='false';publicationForm.querySelectorAll('[type=submit]').forEach(b=>b.disabled=false)}
});
view.addEventListener('click',async e=>{
 const review=e.target.closest('[data-review]'),finish=e.target.closest('[data-finish]'),reset=e.target.closest('[data-reset]');
 if(review)reviewPost(Number(review.dataset.review));
 const button=finish||reset;if(!button)return;
 const id=Number(finish?finish.dataset.finish:reset.dataset.reset),post=state.posts.find(p=>p.id===id);
 if(!confirm(finish?'Concluir agora a publicação desta imagem e legenda no Instagram?':'Você conferiu a conta na rede social e confirmou que este conteúdo NÃO foi publicado? Uma confirmação incorreta pode causar duplicação.'))return;
 button.disabled=true;
 try{if(finish){const result=await api('posts/finish',{id,revision:post.revision,confirmed:true});notify(result.status==='processing'?'A Meta ainda está preparando a imagem. Aguarde e confira novamente.':'A Meta confirmou a publicação.')}else{await api('posts/reset',{id,confirmed_absent:true});notify('Rascunho liberado para revisão.')}await refresh()}catch(error){notify(error.message);await refresh().catch(()=>{})}finally{button.disabled=false}
});

view.addEventListener('click',async e=>{const button=e.target.closest('[data-diagnose]');if(!button)return;const id=Number(button.dataset.diagnose),target=document.querySelector('#diagnostic-'+id);button.disabled=true;target.textContent='Consultando sem publicar…';try{const result=await api('posts/diagnose',{id});const messages=[...result.messages];if(result.image_url){const response=await fetch(result.image_url,{cache:'no-store'});if(!response.ok||!response.headers.get('Content-Type')?.startsWith('image/jpeg'))messages.push('A imagem não respondeu como JPEG público. Confira a rota /media/ em Static files no PythonAnywhere.');else if(response.headers.get('X-Arte-Media-Source')==='application')messages.push('A imagem está sendo servida pelo aplicativo. Configure /media/ em Static files: no plano gratuito a Meta pode não conseguir baixá-la enquanto o aplicativo está ocupado.');else messages.push('A imagem respondeu como JPEG pela rota estática. Isso não confirma o acesso a partir dos servidores da Meta.')}target.innerHTML=messages.map(m=>`<p class="help">${esc(m)}</p>`).join('')}catch(error){target.textContent=error.message}finally{button.disabled=false}});

view.addEventListener('click',async e=>{const button=e.target.closest('[data-test-image]');if(!button)return;const post=state.posts.find(p=>p.id===Number(button.dataset.testImage));if(!confirm('Você conferiu no Instagram que esta postagem não foi publicada? Este teste enviará a imagem e a legenda à API para criar um contêiner NÃO publicado. Não enviará o post ao feed.'))return;button.disabled=true;button.textContent='Testando preparação…';try{await api('posts/test-image',{id:post.id,revision:post.revision,confirmed:true,confirmed_absent:true});notify('A Meta aceitou a preparação. Nada foi publicado no feed. Não use Concluir publicação até revisar o resultado.');await refresh()}catch(error){notify(error.message);await refresh().catch(()=>{})}finally{button.disabled=false}});

view.addEventListener('click',async e=>{const button=e.target.closest('[data-test-meta-image]');if(!button)return;const post=state.posts.find(p=>p.id===Number(button.dataset.testMetaImage));if(!confirm('Confirma que este post ainda não foi publicado? O teste enviará o JPEG à página Facebook vinculada como foto NÃO publicada e usará a imagem da Meta para preparar o Instagram. Não criará um post em nenhum feed.'))return;button.disabled=true;button.textContent='Preparando por arquivo…';try{await api('posts/test-meta-image',{id:post.id,revision:post.revision,confirmed:true,confirmed_absent:true});notify('Preparação aceita pela Meta. Nenhum post foi enviado ao feed.');await refresh()}catch(error){notify(error.message);await refresh().catch(()=>{})}finally{button.disabled=false}});

view.addEventListener('click',async e=>{const button=e.target.closest('[data-cancel-schedule]');if(!button)return;const post=state.posts.find(p=>p.id===Number(button.dataset.cancelSchedule));if(!post?.schedule)return;const when=new Date(post.schedule.due_at*1000).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});if(!confirm(`Cancelar o agendamento de ${when} (São Paulo) e devolver o conteúdo para rascunho?`))return;button.disabled=true;try{await api('posts/cancel-schedule',{id:post.id,revision:post.revision,expected_due_at:post.schedule.due_at});await refresh();notify('Agendamento cancelado. Nada foi enviado por essa ação.')}catch(error){notify(error.message)}finally{button.disabled=false}});

view.addEventListener('click',async e=>{const button=e.target.closest('[data-cancel-automated]');if(!button)return;const item=(state.automated_content||[]).find(value=>value.id===button.dataset.cancelAutomated);if(!item||item.due_at!==Number(button.dataset.dueAt)){notify('O agendamento mudou. Atualize a página.');return}const when=new Date(item.due_at*1000).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});if(!confirm(`Cancelar ${item.product}, agendado para ${when} (São Paulo)? Esta ação remove somente este envio da fila.`))return;button.disabled=true;try{await api('automated-content/cancel',{id:item.id,expected_due_at:item.due_at,confirmed:true});await refresh();notify('Agendamento cancelado. Os demais horários continuam ativos.')}catch(error){notify(error.message);await refresh().catch(()=>{})}finally{button.disabled=false}});

view.addEventListener('click',async e=>{
 const button=e.target.closest('#load-feed-models');if(!button)return;
 button.disabled=true;const message=document.querySelector('#feed-compose-message');message.textContent='Consultando os modelos…';
 try{const result=await api('feed/models',{});const select=document.querySelector('#feed-compose-form [name=file_id]');select.innerHTML='<option value="">Selecione um modelo</option>'+result.models.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');select.disabled=false;document.querySelector('#feed-compose-form [type=submit]').disabled=!result.models.length;message.textContent=result.models.length+' imagens disponíveis. Confira o tema antes de montar.'}catch(error){message.textContent=error.message}finally{button.disabled=false}
});
view.addEventListener('submit',async e=>{
 const form=e.target;if(form.id!=='feed-compose-form')return;e.preventDefault();
 const button=form.querySelector('[type=submit]'),message=form.querySelector('[role=status]');
 const data=Object.fromEntries(new FormData(form));
 const signature=JSON.stringify(data);if(form.dataset.signature!==signature){form.dataset.signature=signature;form.dataset.requestId=crypto.randomUUID()}
 data.request_id=form.dataset.requestId;button.disabled=true;message.textContent='Montando a arte…';
 try{await api('feed/compose',data);await refresh();notify('Arte e legenda salvas como rascunho. Revise a imagem e escolha a conta antes de agendar.')}catch(error){message.textContent=error.message}finally{button.disabled=false}
});

/* Apresentação: indicador das abas. Não altera seleção, foco ou dados. */
(() => {
  'use strict';

  const start = () => {
    const view = document.getElementById('view');
    if (!view) return;

    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    let lastKey = null;
    let indicator = null;
    let animation = null;
    let frame = 0;
    let pendingMotion = false;

    const cancelAnimation = () => {
      if (animation) animation.cancel();
      animation = null;
    };

    // Coordinates use the tabs' padding box, matching absolute CSS positioning.
    const measure = (button, tabs) => {
      const bounds = button.getBoundingClientRect();
      const parent = tabs.getBoundingClientRect();
      return {
        left: bounds.left - parent.left - tabs.clientLeft + tabs.scrollLeft,
        top: bounds.top - parent.top - tabs.clientTop + tabs.scrollTop,
        width: bounds.width,
        height: bounds.height,
      };
    };

    const styles = (bounds) => ({
      left: `${bounds.left}px`,
      top: `${bounds.top}px`,
      width: `${bounds.width}px`,
      height: `${bounds.height}px`,
    });

    const update = (allowMotion) => {
      cancelAnimation();
      const tabs = view.querySelector('.studio-tabs');
      const active = tabs?.querySelector('button[data-content-tab].active');

      if (!tabs || !active) {
        indicator = null;
        return;
      }

      const key = active.getAttribute('data-content-tab');
      const previous = lastKey === null ? null : Array.from(
        tabs.querySelectorAll('button[data-content-tab]'),
      ).find((button) => button.getAttribute('data-content-tab') === lastKey);
      const target = measure(active, tabs);
      const origin = previous ? measure(previous, tabs) : null;

      indicator = tabs.querySelector('.studio-tab-indicator');
      if (!indicator) {
        indicator = document.createElement('span');
        indicator.className = 'studio-tab-indicator';
        indicator.setAttribute('aria-hidden', 'true');
        indicator.style.pointerEvents = 'none';
        tabs.prepend(indicator);
      }

      Object.assign(indicator.style, styles(target));
      tabs.classList.add('has-tab-indicator');
      indicator.style.visibility = target.width > 0 && target.height > 0
        ? 'visible' : 'hidden';

      const changed = lastKey !== null && lastKey !== key;
      lastKey = key;
      if (
        allowMotion && changed && origin && target.width > 0 && target.height > 0 &&
        origin.width > 0 && origin.height > 0 && !reducedMotion.matches &&
        typeof indicator.animate === 'function'
      ) {
        animation = indicator.animate([styles(origin), styles(target)], {
          duration: 220,
          easing: 'cubic-bezier(.22, .8, .25, 1)',
        });
      }
    };

    const schedule = (allowMotion) => {
      // A resize/reduced-motion update overrides motion in the same frame.
      pendingMotion = frame ? pendingMotion && allowMotion : allowMotion;
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        const allow = pendingMotion;
        frame = 0;
        pendingMotion = false;
        update(allow);
      });
    };

    // Indicator changes are nested under tabs and cannot retrigger this observer.
    const observer = new MutationObserver(() => schedule(true));
    observer.observe(view, { childList: true });
    window.addEventListener('resize', () => schedule(false), { passive: true });
    if (document.fonts?.ready) document.fonts.ready.then(() => schedule(false));

    const motionChanged = () => {
      cancelAnimation();
      schedule(false);
    };
    if (typeof reducedMotion.addEventListener === 'function') {
      reducedMotion.addEventListener('change', motionChanged);
    } else {
      reducedMotion.addListener(motionChanged);
    }

    update(false);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
})();
